  {"id": 3, "name": "Paradise Lost", "description": "Complete Chapter 1.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete Chapter 1. Chapter trophies can pop a little late — PowerPyx notes the first three pop once you clear the first mission or two of the next chapter, so don't worry if it doesn't appear the instant the chapter ends.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 4, "name": "T**s Ass Drug Money", "description": "Complete Chapter 2.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete Chapter 2.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 5, "name": "Vice City, Baby!", "description": "Complete Chapter 3.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete Chapter 3.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 6, "name": "Top Of The World, Ma", "description": "Complete Chapter 4.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete Chapter 4.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 7, "name": "You Gotta Know When to Get Off", "description": "Complete the final mission.", "grade": "gold", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the final mission in Chapter 5. Once the credits roll, free roam continues and everything left on the 100% checklist is still open — there is no mission replay, so this is the point the cleanup begins.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 8, "name": "Trust", "description": "Complete Breakfast Run.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission Breakfast Run. It unlocks automatically as you play through the story.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 9, "name": "Break the Bank", "description": "Complete The Cartel Heist.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission The Cartel Heist.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 10, "name": "Family Matters", "description": "Complete Child's Play.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission Child's Play.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 11, "name": "DWNFALL", "description": "Complete Headliners.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission Headliners.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 12, "name": "Hi-Jacked", "description": "Complete VCIA Takedown.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission VCIA Takedown.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 13, "name": "Snow Storm", "description": "Complete Operation Savage Glory.", "grade": "bronze", "hidden": true, "kind": "story", "missable": false, "roadmap": 1, "guide": "Story trophy, unmissable. Complete the mission Operation Savage Glory.", "source": "Official trophy description (PlayStation); PowerPyx"},
  {"id": 14, "name": "A Long Road", "description": "Attain 100% Completion.", "grade": "gold", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "guide": "Reach 100% completion on the in-game checklist (Progress, then Stats, then 100% Completion — it only becomes visible after the story, but progress made during the story already counts). PowerPyx calls it the hardest trophy and the checklist lenient, closer to 60% true completion: you need 70 of the 80 challenges, 300 stunts, 200 of 277 vehicles, 100 of 255 animals and 50 of 66 weapons. Robberies, underwater discoveries, shooting ranges, drone races and Bret's quests need everything. Nothing on the checklist is missable — it can all be finished in free roam after the credits.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap; GTABase"},
  {"id": 15, "name": "Cunning Stunts", "description": "Complete 250 Stunts.", "grade": "silver", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 250, "guide": "Complete any 250 stunts. There are 397 in total across four kinds: 130 stunt jumps (ramps), 202 flights under bridges, 40 knife flights between buildings and 25 base jumps. The 100% checklist needs 300, so keep going past this trophy — the stunt jumps are the easiest to grind, and a plane makes the bridge flights fast.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 16, "name": "Master of None", "description": "Try each type of activity once.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "count": 9, "guide": "Try each of the 9 activity types once: fishing, hunting, golf, shooting ranges, pool, basketball, a video game, a race and a stunt. You don't need to win or finish anything — just try each one. Most of these come naturally while chasing other trophies.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 17, "name": "The Shootist", "description": "Earn a gold medal in all Shooting Range challenges.", "grade": "silver", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 42, "guide": "Earn a gold medal in all 42 Shooting Range challenges. There are no difficulty settings, and PowerPyx says the gold medals aren't too difficult — take your time, learn each range's pattern, and remember you only need gold in the ranges, not in the 80 challenges, for this one. The 100% checklist also needs all 42.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 18, "name": "Top Fun", "description": "Win a Top Fun Drone Race at every location.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 14, "guide": "Win a Top Fun drone race at every one of the 14 locations. You only need one win per location, not every race. The 100% checklist needs all drone races, so this trophy comes on the way.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 19, "name": "Earn Cash, Not Kudos", "description": "Win 20 different races.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 20, "guide": "Win 20 different races. Any race type counts — road, off-road, boat, air — as long as each win is a race you haven't won before. The 100% checklist needs 30 different race wins, so keep racing past this one.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 20, "name": "Baited My Tackle", "description": "Beat Cal in a fishing challenge.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Beat Cal in a fishing challenge. You meet Cal in Chapter 1; after that he texts you a fishing spot. Head there, take the challenge and out-fish him. Fishing also counts toward the activity types for Master of None.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 21, "name": "Stick Fiddler", "description": "Complete an arcade game.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Complete an arcade game — play any one in-game video game through to the end. Three games run on the TV at home and a fourth sits on arcade machines around Leonida. Pick the shortest one and see it through; dying or quitting early doesn't count.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 22, "name": "Road to Rehabilitation", "description": "Complete the final mission for Andy.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Complete the final mission for Andy. This is a Lucia-only stranger strand that starts with a phone call in Chapter 3. Follow the strand through its missions until Andy's story ends. Stranger strands can be finished after the story, so it isn't missable — just answer the call when it comes.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 23, "name": "This Was No Boat Accident", "description": "Complete the final mission for Kenton.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Complete the final mission for Kenton. His strand is treasure diving: 7 shipwrecks in total. Kenton goes quiet after Chapter 1 and returns later in the story, so don't panic if he disappears — he comes back, and the trophy isn't missable.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 24, "name": "The Lone Rider", "description": "Complete the final mission for Billy.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Complete the final mission for Billy. His strand runs out of the mud club in Kelly County and opens in Chapter 2. Work through Billy's missions until the strand ends.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 25, "name": "Strangers & Freaks", "description": "Complete 8 mission strands for strangers across the state of Leonida.", "grade": "silver", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "count": 8, "guide": "Complete 8 mission strands for strangers across Leonida. Only some side questlines count — PowerPyx is still confirming exactly which ones — so finish every stranger strand you find, including Andy, Kenton, Billy, Randy and Tyrone. Strangers & Freaks is not part of the 100% checklist, so it may still be open after the cleanup.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 26, "name": "Supply & Demand", "description": "Complete the final mission for Randy.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Complete the final mission for Randy. His strand is a wish list of 16 sports cars to deliver, and it opens in Chapter 3. Steal or buy the cars on the list and deliver them until Randy's strand ends.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 27, "name": "Spin On This!", "description": "Complete the final mission for Tyrone.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Complete the final mission for Tyrone. His strand is shutting down drug labs around Vice City, Jason only, from Chapter 3. Clear the labs Tyrone marks until the strand ends.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 28, "name": "Positive Mental Attitude", "description": "Meditate at every spot across Leonida.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": true, "roadmap": 1, "count": 18, "guide": "Meditate at every spot across Leonida — 18 spots in 10 locations, as both Jason and Lucia. THIS IS THE ONLY TROPHY THAT MAY BE MISSABLE. During Chapter 1, one morning at Jason's house, Lucia says she is going to meditate and walks out to the balcony. Follow her and accept the optional meditation — it is gone after Chapter 1, and there is no mission replay. PowerPyx reports the balcony meditation raises the counter but isn't marked as a spot like the other 18, so it is unconfirmed whether the trophy needs it — do it anyway, it takes a minute and removes the risk. Keep a manual save at the start of every chapter just in case. The 100% checklist only needs 15 of the 18 spots, so this trophy is the only reason to be careful.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap; GTABase"},
  {"id": 29, "name": "Fair Game", "description": "Hunt a unique animal for Bret.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 1, "guide": "Hunt a unique animal for Bret. Jason only, from Chapter 2. PowerPyx has not yet confirmed which animal triggers it — clearing all 15 of Bret's target decks, which the 100% checklist needs anyway, should cover it. Work through Bret's hunting quests and the trophy should come with them.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 30, "name": "Don't Touch My Deck", "description": "Complete 3 Collectible Card sets.", "grade": "silver", "hidden": false, "kind": "collectibles", "missable": false, "roadmap": 2, "count": 3, "guide": "Complete 3 collectible card sets out of the 18 in the game. Cards are found around Leonida — check shops, hideouts and points of interest as you explore, and trade or buy the ones you're missing. You don't need all 18 sets, just any 3 complete ones.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 31, "name": "You WAiNKer!", "description": "WAiNK It at 100 locations.", "grade": "silver", "hidden": false, "kind": "collectibles", "missable": false, "roadmap": 2, "count": 100, "guide": "WAiNK It at 100 locations. Open the WAiNK phone app and scan landmarks, curiosities and sculptures as you travel — anything scannable counts. The 100% checklist also needs 100, so this trophy and the checklist target are the same.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 32, "name": "One Last Thing", "description": "Complete 50 Challenges.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 50, "guide": "Complete 50 challenges out of the 80 in the game. Challenges cover stunts, races, shooting ranges and more, so this comes naturally while working through the rest of the list. The 100% checklist needs 70, and you can skip the hardest ones.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 33, "name": "Hot Together", "description": "Lose a 4 star Wanted Level with your partner and escape the heat.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Lose a 4-star wanted level with your partner along and escape the heat. This is possible once Jason and Lucia can roam together, from Chapter 2. The easy way: bank jobs give you 4 stars anyway, so finish a bank vault robbery with your partner and then lose the cops. Lay low, break line of sight, and wait for the wanted level to drop.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 34, "name": "Retail Therapy", "description": "Rob 3 shops back-to-back with your partner without losing your Wanted Level.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Rob 3 shops back-to-back with your partner without losing your wanted level. Keep the wanted level alive between shops — don't lose the cops in between — and rob the third shop while it's still active. PowerPyx says the trophy pops about 30 seconds after the third robbery.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 35, "name": "Whip It Good", "description": "Discover 100 vehicles.", "grade": "bronze", "hidden": false, "kind": "collectibles", "missable": false, "roadmap": 1, "count": 100, "guide": "Discover 100 vehicles. Scanning a vehicle with the WAiNK app is enough — you don't have to drive it or own it. Scan every new vehicle you see during the story; the 100% checklist needs 200 of the 277 base model vehicles, so this habit pays off twice.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 36, "name": "Gunslinger", "description": "Take down 5 enemies in a single use of Combat Focus.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Take down 5 enemies in a single use of Combat Focus. PowerPyx reports gang members count, while soldiers, police and civilians seem not to. Pick a gang fight with plenty of enemies close together, trigger Combat Focus, and drop five before it ends.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 37, "name": "Catch Me If You Can", "description": "Make an unscheduled departure at VCIA.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Make an unscheduled departure at VCIA — steal a passenger jet docked at a gate at Vice City International Airport and fly about 1 km away from it. Expect a wanted level the moment you take it; just get airborne and put distance between you and the airport.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 38, "name": "Challenging Tank", "description": "Kinda hot in these Rhinos.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Kinda hot in these Rhinos — steal a military tank. PowerPyx found tanks at Mile Zero Air Station in the southwest of the map. Drive in, grab one, and survive the response long enough for the trophy to pop.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 39, "name": "Sneakthief", "description": "Rob a jewelry store without being detected.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Rob a jewelry store without being detected. You need the Snap Gun, which a Chapter 3 main mission gives you — so this can't be done before then. Case the store, use the Snap Gun to crack the cases quietly, and get out before anyone spots you.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 40, "name": "Maximum Withdrawal", "description": "Rob 5 Bank Vaults and escape.", "grade": "silver", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 5, "guide": "Rob 5 bank vaults and escape. Bank jobs open through an optional mission in Chapter 4. There are 8 vaults in total and the 100% checklist needs all of them, so plan to hit every one. Bring your partner — bank jobs are also the easiest way to get the 4-star wanted level for Hot Together.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 41, "name": "A Classic Blitz Play", "description": "Rob an Armored Truck and escape.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Rob an armored truck and escape. The first bank job counts toward this, or you can blow open a truck's back door with a sticky bomb earlier in the game. Once the cash is out, lose the cops and the trophy pops.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 42, "name": "The Goodtime State", "description": "Explore all of Leonida.", "grade": "bronze", "hidden": false, "kind": "collectibles", "missable": false, "roadmap": 2, "guide": "Explore all of Leonida — clear the fog from the entire map. A plane is fastest: fly a grid over the state and watch the map fill in. The last corners are usually the islands and the far southwest, so check the map for any fog left after your first pass.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 43, "name": "Pest Control", "description": "Rob an Illegal Operation belonging to each gang.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 9, "guide": "Rob an illegal operation belonging to each gang — 9 gangs in total. The 100% checklist needs all 39 operations, so you'll be hitting them anyway. Mark each gang off as you rob its first operation.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 44, "name": "In The Beginning…", "description": "Enjoy a cocktail with a view on Ocean Beach.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Enjoy a cocktail with a view on Ocean Beach. No guide has pinned down the exact method yet as of launch day — the name is a nod to the opening of the original Vice City, so look for a beachfront bar on Ocean Beach and order a drink with the view. Treat this as unconfirmed for now.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap (method unconfirmed at launch)"},
  {"id": 45, "name": "Capital Offense", "description": "Smash your way out of a vehicle showroom in classic style.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Smash your way out of a vehicle showroom in classic style. No guide has pinned down the exact method yet as of launch day. Try driving a car straight through a showroom's front window — the classic GTA way out. Treat this as unconfirmed until players report back.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap (method unconfirmed at launch)"},
  {"id": 46, "name": "Let’s Go Bowling", "description": "Follow-through at the Kolt & Associates' bowling alley.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Follow-through at the Kolt & Associates' bowling alley. Take all 3 key valuables from the Kingpin Bowling gang operation in Port Gellhorn. The robbery comes back later if you miss anything, so it is not missable — just clear the operation and grab all three valuables.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 47, "name": "Personal Best", "description": "A partnership with mass appeal.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "A partnership with mass appeal — max out strength on both Jason and Lucia. Work out together and both characters make progress at the same time. Gyms and workout spots are the way; it is a grind, so fold it into your free-roam cleanup.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 48, "name": "Actions Speak Louder", "description": "Choices made (for better or worse).", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "count": 500, "guide": "Choices made, for better or worse — do 500 things that change your criminal profile. It comes naturally over a full playthrough: crimes, choices and chaos all feed the profile. You don't need to chase it; check your profile under Progress and it will be most of the way there by the end of the story.", "source": "GTABase (single source); PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 49, "name": "Bad Luck, I Guess", "description": "Second time's the charm.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Second time's the charm. No guide has pinned down the method yet as of launch day — PowerPyx suspects a link to a Payday Loans store. Treat this as unconfirmed: keep an eye on the Payday Loans stores and try their services twice.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap (method unconfirmed at launch)"},
  {"id": 50, "name": "The Truth Is Out There", "description": "What the hell just happened?", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "What the hell just happened? No guide has pinned down the method yet as of launch day — PowerPyx suspects a UFO questline. If the UFO thread exists, it likely starts with a strange sighting or signal somewhere remote in Leonida. Treat this as unconfirmed until players report back.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap (method unconfirmed at launch)"},
  {"id": 51, "name": "Ten Pin", "description": "Bowl 'em over with a melee drive-by.", "grade": "bronze", "hidden": true, "kind": "activities", "missable": false, "roadmap": 3, "guide": "Bowl 'em over with a melee drive-by. No guide has pinned down the exact method yet as of launch day — the in-game hint points to a melee attack from a moving vehicle, and PowerPyx suspects a kick from a motorcycle. Try a melee strike from a moving bike at a pedestrian and see if it pops. Treat this as unconfirmed for now.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap (method unconfirmed at launch)"},
  {"id": 52, "name": "Dime on the Dollar", "description": "Earn $250,000 laundering Marked Bills through your contacts.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 250000, "guide": "Earn $250,000 laundering Marked Bills through your contacts. Marked bills come from robberies, and the total adds up across all of them. The dye pack jammer — needed to launder the bills — unlocks in a Chapter 3 main mission, so this starts in earnest from Chapter 3 onward.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 53, "name": "Treat Yo Self", "description": "Spend $100,000 across all shops.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 100000, "guide": "Spend $100,000 across all shops. Guns, car mods and tattoos get you there fastest. Spending counts across the whole game, so anything you bought during the story already counts toward it.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 54, "name": "Little Boxes", "description": "Purchase all garage properties.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 8, "guide": "Purchase all garage properties — 8 in total. PowerPyx puts the combined price at about $160,000. The real estate app arrives in Chapter 2, so garages can't be bought before then. Buy them as you can afford them; bank vaults are PowerPyx's pick for the best late-game money.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"},
  {"id": 55, "name": "On the Spot", "description": "Register 10 vehicles to the Scooter Bros app.", "grade": "bronze", "hidden": false, "kind": "activities", "missable": false, "roadmap": 2, "count": 10, "guide": "Register 10 vehicles to the Scooter Bros app. You need garage space first, so pair this with Little Boxes — buy the garages, then register vehicles to the app from them. Any vehicle you own can be registered.", "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap"}
